\end{align}

\label{l:majorcompletion9}
Under the hypotheses of Lemma~\ref{l:circmethod}, uniformly for
\(2\leq U\leq N\) and \(2\leq W\leq N^2\),
\begin{align}\label{e:majorcompletion9}
& \sum_{n<N^2}\left|
